```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^(\#+)\s*(.*?)\n)");
    std::smatch match;
    while (std::regex_search(markdown, match, re)) {
        std::string level = match[1];
        std::string text = match[2];
        html = html + "<h" + level + ">" + text + "</h" + level + ">\n";
    }
    return html;
}
```

